import unittest
class TestNameAge(unittest.TestCase):
    def test_run(self):
        out = run_student_code(inputs=['Frances', '1990'])
        self.assertIn('Frances', out)
        if "31" not in out:
             self.fail("❌ Cálculo de edad incorrecto. Para 1990, la edad debería ser 31.")
        self.assertIn('31', out)

